CREATE TABLE IF NOT EXISTS procurement_source_rules(rule_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,material_master_id TEXT NOT NULL,supplier_id TEXT NOT NULL,priority INTEGER NOT NULL DEFAULT 100,allocation_pct NUMERIC NOT NULL DEFAULT 100,min_order_qty NUMERIC NOT NULL DEFAULT 0,lead_time_days INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,material_master_id,supplier_id));
CREATE TABLE IF NOT EXISTS supplier_performance_snapshot(snapshot_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,supplier_id TEXT NOT NULL,period_key TEXT NOT NULL,on_time_pct NUMERIC NOT NULL DEFAULT 0,quality_accept_pct NUMERIC NOT NULL DEFAULT 0,price_score NUMERIC NOT NULL DEFAULT 0,overall_score NUMERIC NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,supplier_id,period_key));
CREATE TABLE IF NOT EXISTS procurement_rfqs(rfq_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,location_id TEXT NOT NULL,material_master_id TEXT NOT NULL,required_qty NUMERIC NOT NULL,uom TEXT NOT NULL,required_date TEXT,supplier_ids TEXT,status TEXT NOT NULL DEFAULT 'DRAFT',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS procurement_quotes(quote_id TEXT PRIMARY KEY,rfq_id TEXT NOT NULL,supplier_id TEXT NOT NULL,unit_price NUMERIC NOT NULL,landed_cost NUMERIC NOT NULL DEFAULT 0,lead_time_days INTEGER NOT NULL DEFAULT 0,quality_score NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'RECEIVED',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS procurement_requisitions(requisition_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,location_id TEXT NOT NULL,material_master_id TEXT NOT NULL,supplier_id TEXT,qty NUMERIC NOT NULL,uom TEXT NOT NULL,required_date TEXT,source_suggestion_id TEXT,source_rfq_id TEXT,status TEXT NOT NULL DEFAULT 'DRAFT',approved_by TEXT,approved_at TIMESTAMP,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
